@layer base {
  :root {
    --font-sans: var(--font-sans, 'Inter Tight', -apple-system, BlinkMacSystemFont, sans-serif);
    --font-serif: var(--font-serif, 'Cormorant Garamond', Georgia, serif);
    --font-mono: var(--font-mono, 'JetBrains Mono', monospace);
    --color-void: #000000;
    --color-starlight: #f6f1ea;
    --color-amber: #ffb36b;
    --color-doppler-blue: #e6f0ff;
    --color-doppler-red: #ff8a3d;
  }

  html,
  body,
  .pg-body {
    background-color: #000000;
    color: #f6f1ea;
    font-family: var(--font-sans);
    margin: 0;
    padding: 0;
  }
}

.font-display {
  font-family: var(--font-sans);
}

.font-editorial {
  font-family: var(--font-serif);
}

.font-mono-tech {
  font-family: var(--font-mono);
  font-variant-numeric: tabular-nums;
}

/* Fallback visibility management */
html[data-perigee-mode="experience"] #perigee-fallback-root {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: 0;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  border: 0;
  pointer-events: none;
}

@media (prefers-reduced-motion: reduce) {
  #perigee-experience-root {
    display: none !important;
  }
  #perigee-fallback-root {
    position: static !important;
    width: auto !important;
    height: auto !important;
    clip: auto !important;
    overflow: visible !important;
    pointer-events: auto !important;
  }
}

// PERIGEE — Webflow Custom Code Runtime Bridge
// Dependencies: three, gsap, lenis
import Lenis from "https://cdn.jsdelivr.net/npm/lenis@1.3.27/+esm";
import gsap from "https://cdn.jsdelivr.net/npm/gsap@3.15.0/+esm";
import * as THREE from "https://cdn.jsdelivr.net/npm/three@0.186.1/+esm";
const prefersReducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
if (!prefersReducedMotion) {
  const lenis = new Lenis({ autoRaf: true });
  window.__openlandingLenis = lenis;
}
